mapper.insert:
INSERT INTO file (
    file_name
    , save_file_name
    , file_path
    , file_extension
    , file_size
    , rgtr
    , request_source
    , checksum
    , prsinfo_yn
) VALUES (
    #{fileName}
    , #{saveFileName}
    , #{filePath}
    , #{fileExtension}
    , #{fileSize}
    , #{rgtr}
    , #{requestSource}
    , #{checksum}
    , #{prsInfoYn}
)

INSERT INTO file_download_log (
    file_idx
    , file_name
    , user_id
    , access_ip
    , request_source
) VALUES (
    #{fileIdx}
    , #{fileName}
    , #{userId}
    , #{accessIp}
    , #{requestSource}
);

mapper.update:
UPDATE file
SET del_yn = CASE id

        WHEN #{item.fileIdx} THEN #{item.delYn}

    END,
    del_dt = CASE id

        WHEN #{item.fileIdx} THEN #{item.delDt}

    END
WHERE id IN

    #{item.fileIdx}

mapper.select:
/* FileMapper.selectFileInfo */ SELECT a1.`id` AS fileIdx , a1.file_name AS fileName , a1.save_file_name AS saveFileName , a1.file_path AS filePath , a1.file_extension AS fileExtension , a1.file_size AS fileSize , a1.rgtr , a1.reg_dt AS regDt , a1.request_source AS requestSource , a1.checksum AS checksum , a1.del_yn AS delYn , a1.prsinfo_yn AS prsInfoYn
, CASE WHEN a1.rgtr = #{rgtr} OR ( /* 요청 교사와 생성자(교사/학생)가 같은 group_id에 속하는 경우만 허용 */ EXISTS ( SELECT 1 FROM group_info gi_req_tc INNER JOIN user u_req_tc ON gi_req_tc.host_user_no = u_req_tc.user_no INNER JOIN group_info gi_creator ON gi_req_tc.group_id = gi_creator.group_id WHERE u_req_tc.tc_id = #{rgtr} AND ( EXISTS ( SELECT 1 FROM user u_creator_tc WHERE u_creator_tc.user_no = gi_creator.host_user_no AND u_creator_tc.tc_id = a1.rgtr ) OR EXISTS ( SELECT 1 FROM group_member gm_creator_st WHERE gm_creator_st.group_id = gi_creator.group_id AND gm_creator_st.stdt_id = a1.rgtr ) ) ) ) OR ( EXISTS ( SELECT 1 FROM group_member gm_req_st WHERE gm_req_st.stdt_id = #{rgtr} ) AND EXISTS ( SELECT 1 FROM group_info gi_creator_tc2 INNER JOIN user u_creator_tc2 ON gi_creator_tc2.host_user_no = u_creator_tc2.user_no WHERE u_creator_tc2.tc_id = a1.rgtr ) ) THEN 'Y' ELSE 'N' END downloadAuthYn
, 'Y' AS downloadAuthYn
FROM file a1 WHERE 1=1
AND id = #{fileIdx}
AND file_path = #{filePath} AND file_name = #{fileName} ORDER BY `id` DESC LIMIT 1

/* FileMapper.selectFileInfoWithPionada */ SELECT a1.`id` AS fileIdx , a1.file_name AS fileName , a1.save_file_name AS saveFileName , a1.file_path AS filePath , a1.file_extension AS fileExtension , a1.file_size AS fileSize , a1.rgtr , a1.reg_dt AS regDt , a1.request_source AS requestSource , a1.checksum AS checksum , a1.del_yn AS delYn , a1.prsinfo_yn AS prsInfoYn FROM file a1 WHERE 1=1
AND id = #{fileIdx}
AND file_path = #{filePath} AND file_name = #{fileName} ORDER BY `id` DESC LIMIT 1

/* FileMapper.selectFileInfoWithPartnerActivity */ SELECT a1.`id` AS fileIdx , a1.file_name AS fileName , a1.save_file_name AS saveFileName , a1.file_path AS filePath , a1.file_extension AS fileExtension , a1.file_size AS fileSize , a1.rgtr , a1.reg_dt AS regDt , a1.request_source AS requestSource , a1.checksum AS checksum , a1.del_yn AS delYn , a1.prsinfo_yn AS prsInfoYn
, CASE WHEN a1.rgtr = #{rgtr} OR ( /* 요청 교사와 생성자(교사/학생)가 같은 group_id에 속하는 경우만 허용 */ EXISTS ( SELECT 1 FROM group_info gi_req_tc INNER JOIN user u_req_tc ON gi_req_tc.host_user_no = u_req_tc.user_no INNER JOIN group_info gi_creator ON gi_req_tc.group_id = gi_creator.group_id WHERE u_req_tc.tc_id = #{rgtr} AND ( EXISTS ( SELECT 1 FROM user u_creator_tc WHERE u_creator_tc.user_no = gi_creator.host_user_no AND u_creator_tc.tc_id = a1.rgtr ) OR EXISTS ( SELECT 1 FROM group_member gm_creator_st WHERE gm_creator_st.group_id = gi_creator.group_id AND gm_creator_st.stdt_id = a1.rgtr ) ) ) ) OR ( EXISTS ( SELECT 1 FROM group_member gm_req_st WHERE gm_req_st.stdt_id = #{rgtr} ) AND EXISTS ( SELECT 1 FROM group_info gi_creator_tc2 INNER JOIN user u_creator_tc2 ON gi_creator_tc2.host_user_no = u_creator_tc2.user_no WHERE u_creator_tc2.tc_id = a1.rgtr ) ) THEN 'Y' ELSE 'N' END downloadAuthYn
, 'Y' AS downloadAuthYn
FROM file a1 WHERE 1=1
AND id = #{fileIdx}
AND file_path = #{filePath} AND file_name = #{fileName} ORDER BY `id` DESC LIMIT 1

/* FileMapper.selectTcListFromCreator */
SELECT u.tc_id
FROM group_info gi
         INNER JOIN user u ON gi.host_user_no = u.user_no
         INNER JOIN group_member gm ON gi.group_id = gm.group_id
WHERE gm.stdt_id = #{creator}

/* FileMapper.selectFileAuthStudent */
SELECT gm.stdt_id
FROM group_info gi
         INNER JOIN user u ON gi.host_user_no = u.user_no
         INNER JOIN group_member gm ON gi.group_id = gm.group_id
WHERE u.tc_id = #{creator}
  AND gm.stdt_id = #{reader}
